import{_ as t,o as a,c as s,ae as i}from"./chunks/framework.DQC_QtFV.js";const w=JSON.parse('{"title":"Memory","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/console/memory.md","filePath":"en/guide/console/memory.md","lastUpdated":1793162416000}'),o={name:"en/guide/console/memory.md"};function n(r,e,h,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h1><p>The memory page is the notes browser. Notes are written and edited by the assistant itself and are its only long-term memory; each carries a summary of at most 200 characters, and every list shows the summary, never the body - so scanning many notes is cheap, and a body is read only when it is needed.</p><h2 id="the-list-and-its-filters" tabindex="-1">The list and its filters <a class="header-anchor" href="#the-list-and-its-filters" aria-label="Permalink to &quot;The list and its filters&quot;">​</a></h2><p>The toolbar holds the search box, the status filter (active / archived / all), the visibility filter (open / private / secret) and more, with the advanced filters as a disclosure at the end. Each row of the result list is one note: title, summary, status, visibility, window. Clicking one opens its detail - the body, the revision history including tombstones, and each revision&#39;s anchor context: which message and turn it came from, which stretch of the conversation it covers.</p><p>The filters and the open note ride in the URL, so a filtered list or one note can be linked and reloaded. The 常驻 switch in the detail is the owner&#39;s handle: a pinned note is in every active set whatever its usage score, and the assistant has no way to set it itself.</p><h2 id="设置-two-limits" tabindex="-1">设置: two limits <a class="header-anchor" href="#设置-two-limits" aria-label="Permalink to &quot;设置: two limits&quot;">​</a></h2><p>The 设置 popover in the page header holds two numbers; a change takes effect at the next window:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it is</th></tr></thead><tbody><tr><td>活跃笔记上限</td><td>20</td><td>the most active notes a new window keeps</td></tr><tr><td>每窗口新笔记</td><td>10</td><td>the most new notes one window may write</td></tr></tbody></table><p>The stack picks the active set as each window opens: the owner&#39;s pinned notes, the notes written or edited in the closing window, then the rest by measured usage. Everything else stays archived and searchable. The mechanism is on <a href="./../how-it-works.html">How it works</a>.</p>',9)])])}const p=t(o,[["render",n]]);export{w as __pageData,p as default};
